const servers=[];
const rows=[{id:'b',name:' Pistachio ',price:230},{id:'a',name:'Pistachio mini',price:100},{id:'b',name:'ignored',price:1},{id:'z',name:'Lemon',price:120}];
const ndjson=values=>values.map(row=>JSON.stringify(row)).join('\n')+'\n';
async function write(name,value){await fs.writeFile(path.join(root,name),value);}
async function close(server){if(!server?.listening)return;await new Promise((resolve,reject)=>{server.close(error=>error?reject(error):resolve());server.closeAllConnections();});}
async function listen(server){servers.push(server);await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',()=>{server.off('error',reject);resolve();});});}
async function request(server,route='/products',method='GET'){
  return new Promise((resolve,reject)=>{
    const outgoing=http.request({host:'127.0.0.1',port:server.address().port,path:route,method,agent:false},incoming=>{
      let text='';incoming.setEncoding('utf8');incoming.on('data',chunk=>text+=chunk);
      incoming.on('end',()=>{try{resolve({status:incoming.statusCode,body:JSON.parse(text),type:incoming.headers['content-type'],length:Number(incoming.headers['content-length']),actualLength:Buffer.byteLength(text),allow:incoming.headers.allow??null});}catch(error){reject(error);}});
      incoming.on('error',reject);
    });outgoing.on('error',reject);outgoing.setTimeout(1500,()=>outgoing.destroy(new Error('fixture request timeout')));outgoing.end();
  });
}
const deferred=()=>{let resolve,reject;const promise=new Promise((yes,no)=>{resolve=yes;reject=no;});return {promise,resolve,reject};};
async function gate(promise){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('expected operation did not start')),900);})]);}finally{clearTimeout(timer);}}
async function errorOf(action){try{await action();return null;}catch(error){return {name:error?.name??'undefined',code:error?.code??null,line:error?.line??null};}}

try {
function normalizeProduct(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) ||
      !['id', 'name', 'price'].every(key => Object.hasOwn(value, key)) ||
      typeof value.id !== 'string' || typeof value.name !== 'string' ||
      !Number.isSafeInteger(value.price) || value.price < 0) throw new TypeError('invalid product');
  const id = value.id.trim().normalize('NFC');
  const name = value.name.trim().normalize('NFC');
  if (!id || !name) throw new TypeError('missing product text');
  return { id, name, price: value.price };
}
function normalizeQuery(value) {
  if (typeof value !== 'string') throw new TypeError('query must be a string');
  return value.trim().normalize('NFC').toLowerCase();
}

function queryProducts(records, options = {}) {
  if (!Array.isArray(records) || !options || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError('records and options are invalid');
  }
  const { query = '', maxPrice = Infinity, limit = Infinity } = options;
  const normalized = normalizeQuery(query);
  if (typeof maxPrice !== 'number' || Number.isNaN(maxPrice) || maxPrice < 0 ||
      !(limit === Infinity || Number.isSafeInteger(limit) && limit >= 0)) throw new TypeError('invalid query options');
  const unique = new Map();
  for (let index = 0; index < records.length; index++) {
