function makeTarget(multiplier=1) {
 const target={
  async queryProductFile(directory,file,options={}){
   const text=await fs.readFile(path.join(directory,file),'utf8');
   const records=text.trim()?text.trim().split('\n').map(JSON.parse):[];
   return queryProducts(records.map(row=>({...row,price:row.price*multiplier})),options);
  },
