const initial=review.getState().status;
const result=await review.run([
 {id:'file',check:async({target,workspaceRoot})=>{trace.push('file:start');const report=await target.queryProductFile(workspaceRoot,'products.ndjson');trace.push('file:end');return report.count===3&&report.total===450;}},
